import json
# Recreate baseline from known project file contents
baseline = {
    'Api.csproj': {'System.Text.Json': '10.0.1', 'Azure.Identity': '1.13.2'},
    'Worker.csproj': {'Microsoft.Extensions.Hosting': '8.0.1', 'System.Text.Json': '8.0.4', 'OpenTelemetry.Extensions.Hosting': '1.15.0'},
    'Shared.csproj': {'System.Text.Json': '10.0.1', 'Azure.Identity': '1.11.4'},
    'Tests.csproj': {'xunit': '2.9.3', 'System.Text.Json': '10.0.1'},
}
with open('after-cpm-packages.json') as f:
    after = json.load(f)
after_map = {}
for proj in after['projects']:
    name = proj['path'].split('/')[-1]
    after_map[name] = {}
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            after_map[name][pkg['id']] = pkg['resolvedVersion']

print('CHANGES:')
for proj in sorted(baseline):
    for pkg in sorted(baseline[proj]):
        old = baseline[proj][pkg]
        new = after_map.get(proj, {}).get(pkg, 'MISSING')
        if old != new:
            print(f'  {proj}: {pkg} {old} -> {new}')

print('UNCHANGED:')
for proj in sorted(baseline):
    for pkg in sorted(baseline[proj]):
        old = baseline[proj][pkg]
        new = after_map.get(proj, {}).get(pkg, 'MISSING')
        if old == new:
            print(f'  {proj}: {pkg} {old}')
"

